agent_sql_query:
SELECT COUNT(*) AS arrest_count
FROM   crime_incidents
WHERE  "ARREST" = TRUE;

SELECT COUNT(*) AS crimes_reported_in_2023
FROM   crime_incidents
WHERE  "YEAR" = 2023;

SELECT DISTINCT "CRIME_CATEGORY"
FROM   crime_incidents
ORDER BY "CRIME_CATEGORY";

SELECT COUNT(*) AS violent_crime_count
FROM   crime_incidents
WHERE  "VIOLENT_CRIME_FLAG" = 1;

SELECT COUNT(*) AS high_severity_crime_count
FROM crime_incidents
WHERE "CRIME_SEVERITY_LEVEL" = 'High';

SELECT DISTINCT "CRIME_SEVERITY_LEVEL"
FROM   crime_incidents
ORDER BY "CRIME_SEVERITY_LEVEL";

SELECT COUNT(*) AS high_risk_crime_count
FROM   crime_incidents
WHERE  LOCATION_RISK_CATEGORY = 'High Risk';

SELECT COUNT(*) AS crimes_in_ward_5
FROM crime_incidents
WHERE "WARD" = '5';

SELECT COUNT(*) AS crimes_in_community_25
FROM   crime_incidents
WHERE  COMMUNITY_AREA = '25';

SELECT COUNT(*) AS violent_crime_count
FROM   crime_incidents
WHERE  CRIME_FBI_CLASSIFICATION = 'Violent Crime';

SELECT COUNT(*) AS crimes_reported_2021
FROM crime_incidents
WHERE "YEAR" = 2021;

SELECT COUNT(*) AS crimes_with_missing_latitude
FROM   crime_incidents
WHERE  LATITUDE IS NULL;

SELECT COUNT(*) AS crimes_updated_on_or_after_2025_01_01
FROM   crime_incidents
WHERE  UPDATED_ON >= DATE '2025-01-01';

SELECT COUNT(DISTINCT "BLOCK") AS distinct_weapon_blocks
FROM   crime_incidents
WHERE  "WEAPON_CRIME_FLAG" = 1;

/* 1. How many distinct years are present in the data */
WITH total_years AS (
    SELECT COUNT(DISTINCT "YEAR") AS yr_cnt
    FROM crime_incidents
),

/* 2. For each district, count the distinct years it appears in */
district_years AS (
    SELECT "DISTRICT"               AS district_id,
           COUNT(DISTINCT "YEAR")   AS yr_cnt
    FROM crime_incidents
    GROUP BY "DISTRICT"
)

/* 3. Keep only those districts whose year‑count matches the total number of years,
      then count those districts */
SELECT COUNT(*) AS districts_with_crime_in_every_year
FROM district_years dy
JOIN total_years ty
      ON dy.yr_cnt = ty.yr_cnt;

ground_truth_sql:
WITH monthly AS (
  SELECT EXTRACT(MONTH FROM "INCIDENT_DATE") AS month, COUNT(*) AS crime_count
  FROM crime_incidents WHERE "YEAR" = 2023 GROUP BY month
)
SELECT month, crime_count, crime_count - LAG(crime_count) OVER (ORDER BY month) AS change_from_prev_month
FROM monthly ORDER BY month;

WITH yearly AS (
  SELECT "YEAR", COUNT(*) AS crime_count FROM crime_incidents GROUP BY "YEAR"
)
SELECT "YEAR", crime_count,
       ROUND(100.0 * (crime_count - LAG(crime_count) OVER (ORDER BY "YEAR")) / LAG(crime_count) OVER (ORDER BY "YEAR"), 2) AS pct_growth
FROM yearly ORDER BY "YEAR";

SELECT dn.district_name, COUNT(*) AS crime_count
FROM crime_incidents ci JOIN district_names dn ON ci."DISTRICT" = dn.district_id
GROUP BY dn.district_name
HAVING COUNT(*) > (
  SELECT AVG(district_total) FROM (
    SELECT COUNT(*) AS district_total FROM crime_incidents GROUP BY "DISTRICT"
  ) t
)
ORDER BY crime_count DESC;

WITH ranked AS (
  SELECT "YEAR", "CRIME_OFFENSE_GROUP", COUNT(*) AS crime_count,
         ROW_NUMBER() OVER (PARTITION BY "YEAR" ORDER BY COUNT(*) DESC) AS rn
  FROM crime_incidents GROUP BY "YEAR", "CRIME_OFFENSE_GROUP"
)
SELECT "YEAR", "CRIME_OFFENSE_GROUP", crime_count FROM ranked WHERE rn = 1 ORDER BY "YEAR";

SELECT COUNT(*) AS duplicate_case_numbers FROM (
  SELECT "CASE_NUMBER" FROM crime_incidents GROUP BY "CASE_NUMBER" HAVING COUNT(*) > 1
) t;

SELECT can.community_area_name, COUNT(*) AS crime_count
FROM crime_incidents ci JOIN community_area_names can ON ci."COMMUNITY_AREA" = can.community_area_id
GROUP BY can.community_area_name
HAVING COUNT(*) > 2 * (
  SELECT AVG(area_total) FROM (
    SELECT COUNT(*) AS area_total FROM crime_incidents GROUP BY "COMMUNITY_AREA"
  ) t
)
ORDER BY crime_count DESC;

SELECT "CRIME_SEVERITY_LEVEL", ROUND(AVG(yearly_count), 2) AS avg_crimes_per_year
FROM (
  SELECT "CRIME_SEVERITY_LEVEL", "YEAR", COUNT(*) AS yearly_count
  FROM crime_incidents GROUP BY "CRIME_SEVERITY_LEVEL", "YEAR"
) t
GROUP BY "CRIME_SEVERITY_LEVEL" ORDER BY avg_crimes_per_year DESC;
